#include <stdio.h>
int main(void) {
    double h1 = 0.95, t1 = 1.0;   /* L1 命中率/命中时间 */
    double h2 = 0.90, t2 = 10.0;  /* L1 miss 后 L2 命中率/时间 */
    double tm = 100.0;            /* 主存时间 */
    double amat = h1 * t1 + (1 - h1) * (t1 + h2 * t2 + (1 - h2) * (t2 + tm));
    printf("L1 命中率 = %.2f, L1 命中时间 = %.0f ns\n", h1, t1);
    printf("L1 miss 后 L2 命中率 = %.2f, L2 时间 = %.0f ns\n", h2, t2);
    printf("主存时间 = %.0f ns\n", tm);
    printf("AMAT = h1*t1 + (1-h1)*(t1 + h2*t2 + (1-h2)*(t2+tm))\n");
    printf("     = %.2f ns\n", amat);
    return 0;
}
